  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C20", "C14", "C03", "C06", "C15", "C13", "C12", "C17"],
  "contradictory_card_ids": ["C22", "C18", "C21"],
  "prediction_basis_card_ids": ["C20"],
  "claims": [
    {
      "claim": "C20 is the most direct threshold-relevant record: compound 4p, an analog sharing the query's pyrazolopyrimidine acrylamide core, had an absolute oral Fpod of 10% in cynomolgus monkeys at 1 mg/kg, below the 20% threshold.",
      "card_ids": ["C20"]
    },
    {
      "claim": "New L3 oral exposure records for close BTK-inhibitor analogs (acalabrutinib C35/C36/C37/C39/C44; rilzabrutinib C40/C42) show measurable human Cmax and rapid Tmax after oral dosing, but they report no absolute F or IV-referenced AUC, so they cannot affirm F>=20% and do not overturn the direct low-F value.",
      "card_ids": ["C35", "C36", "C37", "C39", "C40", "C42", "C44"]
    },
    {
      "claim": "Other human low-F contexts (olcegepant C14, DX-9065a C03/C06, astemizole C15, saquinavir C13, melagatran C12, emixustat C17) are structurally distant and low-transferability; they are consistent with but not decisive for the query.",
      "card_ids": ["C14", "C03", "C06", "C15", "C13", "C12", "C17"]
    },
    {
      "claim": "No affirmative evidence supports F>=20% for the query; the only high animal F values (FK3453 in dogs, C18/C21) are species-specific and not transferable to the query.",
      "card_ids": ["C18", "C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C35", "C36", "C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query is supplied; C20 is a monkey Fpod for an analog, and its exact structural identity with the query is inferred rather than explicit.",
    "New L3 records provide Cmax/Tmax but no absolute F or IV-referenced AUC for the close analogs, so the F>=20% threshold cannot be directly assessed from them.",
    "No experimental solubility, permeability, or first-pass metabolism data for the query are supplied; high logP/logD and primary aromatic amine are proxies.",
    "The query's fasted-state condition is not explicitly matched in most cards; C20 used a Cremophor/DMSO formulation that may alter absorption."
  ],
  "decision_summary": "The most direct threshold-relevant evidence remains C20, an absolute Fpod of 10% in monkeys for a compound sharing the query's pyrazolopyrimidine acrylamide core. New L3 oral exposure records for acalabrutinib and rilzabrutinib show that this structural class can be orally absorbed in humans, but they provide no F values and therefore do not establish F>=20% or overturn the direct low-F measurement. The prediction remains low with moderate confidence."
}

